//! `BRepOffset_Inter2d::ConnexIntByInt` (`BRepOffset_Inter2d.cxx:1830-2094`)
//! and `ConnexIntByIntInVert` (`:2100-2308`): the 2D intersections that involve
//! the edges generated by the offset of a face or of a vertex.
//!
//! `ConnexIntByInt` runs in two phases:
//!
//! 1. every offset edge generated by an edge of `FI` that is already bound in
//!    `Build` is prolonged with `ExtentEdge` (`cxx:1859-1898`) and cached in
//!    `MES`;
//! 2. every consecutive edge pair `(CurE, NextE)` of every wire of `FI`
//!    (`cxx:1908-2092`) is intersected: the pair is resolved into two
//!    oriented edge chains (`Build` / `MES`, `cxx:1967-2000`), the pair of
//!    boundary edges is handed to `RefEdgeInter` (`cxx:2031-2042`), and
//!    `theEdgeIntEdges` records the pair. When neither side has an image the
//!    `CommonVertex` of the two offset edges only has its parameter updated
//!    (`cxx:2075-2088`).
//!
//! `ConnexIntByIntInVert` intersects the edges generated out of a vertex
//! (`Build(Vref)`) with the edges the 3D phase attached to the offset face and
//! among themselves (`cxx:2212-2302`); a coincident pair trims the vertex edge
//! like its partner (`cxx:2242-2246`, `:2265-2269`).
//!
//! Port guards (no OCCT branch changed):
//!
//! * `TopoDS::Edge(OFI.Generated(...))` (`cxx:1888`, `:1956-1959`, `:2181-2183`)
//!   on an unbound shape builds a null edge: the port skips the arrow.
//! * `OFI.Face()` (`cxx:1902`, `:2114`) forced to a `TopoDS_Face`: an unset
//!   face answers `None` and the method returns (`ConnexIntByInt`) / returns
//!   (`ConnexIntByIntInVert`, `void`).
//! * `CommonVertex` (`cxx:1948`, `:2170`) has no vertex when the two edges do
//!   not meet; OCCT would hand `RefEdgeInter` a null reference vertex, the
//!   port skips the pair.
//! * `NCollection_List::First` / `Last` on the empty `NE1seq` / `NE2seq`
//!   (`cxx:2012-2018`) raises in OCCT; the port skips the pair.
//! * `MVE` (`cxx:1849`) is a `HashMap` in the port, so the extension phase
//!   iterates the keys in key order; every step writes an independent entry of
//!   `MES`, so the outcome does not depend on that order.

use std::collections::{HashMap, HashSet};

use crate::abs::{Orientation, ShapeType};
use crate::brep_algo::AsDes;
use crate::brep_algo_image::BRepAlgoImage;
use crate::brep_offset::{Analyse, BRepOffsetOffset, BRepOffsetTool, ShapeMap};
use crate::brep_tools_wire_explorer::WireExplorer;
use crate::shape::{Edge, Face, TopoShape, Wire};
use crate::topo_tools::{explorer_shapes, is_same, shape_map_key, ShapeMapKey};
use crate::topopebrep::tool::adaptor::SurfaceAdaptor;

use super::extent_edge::extent_edge;
use super::orient_edges::{common_vertex, get_edges_oriented_in_face};
use super::ref_edge_inter::ref_edge_inter;
use super::store_vertices::store_on_edge;
use super::vertex_update::update_vertex;
use super::Dmvv;

/// One oriented chain `NEseq` of `cxx:1961` / `:1962`.
type EdgeChain = Vec<Edge>;

/// `theDMVV` / `theEdgeIntEdges` / `FacesWithVerts` of the `ConnexIntByInt`
/// signature, grouped so the call sites stay readable.
pub struct ConnexByIntData<'a> {
    /// `FacesWithVerts` (`NCollection_IndexedMap<TopoDS_Shape>`): insertion
    /// ordered, `IsSame`-unique.
    pub faces_with_verts: &'a mut Vec<TopoShape>,
    /// `theImageVV`.
    pub image_vv: &'a mut BRepAlgoImage,
    /// `theEdgeIntEdges` (`NCollection_DataMap<TopoDS_Shape,
    /// NCollection_List<TopoDS_Shape>>`).
    pub edge_int_edges: &'a mut HashMap<ShapeMapKey, Vec<TopoShape>>,
    /// `theDMVV`.
    pub dmvv: &'a mut Dmvv,
}

/// `ConnexIntByInt(FI, OFI, MES, Build, theAsDes, AsDes2d, Offset, Tol,
/// Analyse, FacesWithVerts, theImageVV, theEdgeIntEdges, theDMVV,
/// theRange)` (`cxx:1830-2094`).
///
/// `mes` is the `NCollection_DataMap<TopoDS_Shape, TopoDS_Shape> MES` the
/// caller shares with the 3D phase; `build` is the read-only `Build` map.
/// `false` is the reference's `return false` on a failed `ExtentEdge`
/// (`cxx:1892-1895`).
#[allow(clippy::too_many_arguments)]
pub fn connex_int_by_int(
    fi: &Face,
    ofi: &BRepOffsetOffset,
    mes: &mut ShapeMap,
    build: &ShapeMap,
    as_des: &AsDes,
    as_des2d: &mut AsDes,
    offset: f64,
    tol: f64,
    analyse: &Analyse,
    data: &mut ConnexByIntData<'_>,
) -> bool {
    // `BRepOffset_Tool::MapVertexEdges(FI, MVE)` (`cxx:1850`).
    let mve = BRepOffsetTool::map_vertex_edges(&fi.0);

    // `cxx:1859-1898`: extend the offset edges that `Build` knows about.
    let mut mve_keys: Vec<ShapeMapKey> = mve.keys().cloned().collect();
    mve_keys.sort();
    for key in mve_keys {
        let Some(list) = mve.get(&key) else {
            continue;
        };
        // `YaBuild` (`cxx:1866-1877`): is any edge of this vertex bound?
        let mut ya_build = false;
        for s in list {
            if build.contains_key(&shape_map_key(s)) {
                ya_build = true;
                break;
            }
        }
        if !ya_build {
            continue;
        }
        for s in list {
            let ei = Edge(s.clone());
            // `if (EI.Orientation() != FORWARD && != REVERSED) continue;`
            // (`cxx:1884-1887`).
            if ei.0.orientation() != Orientation::Forward
                && ei.0.orientation() != Orientation::Reversed
            {
                continue;
            }
            // `TopoDS_Shape aLocalShape = OFI.Generated(EI);
            //  const TopoDS_Edge& OE = TopoDS::Edge(aLocalShape);`
            // (`cxx:1888-1889`); an unbound shape is a null edge in OCCT.
            let Some(oe_shape) = ofi.generated(&ei.0) else {
                continue;
            };
            let oe = Edge(oe_shape);
            // `if (!MES.IsBound(OE) && !Build.IsBound(EI))` (`cxx:1890`).
            if !mes.contains_key(&shape_map_key(&oe.0))
                && !build.contains_key(&shape_map_key(&ei.0))
            {
                // `if (!ExtentEdge(OE, NE, Offset)) return false;`
                // (`cxx:1892-1895`).
                let Some(ne) = extent_edge(&oe, offset) else {
                    return false;
                };
                // `MES.Bind(OE, NE);` (`cxx:1896`).
                mes.insert(shape_map_key(&oe.0), ne.0);
            }
        }
    }

    // `TopoDS_Face FIO = TopoDS::Face(OFI.Face());
    //  if (MES.IsBound(FIO)) FIO = TopoDS::Face(MES(FIO));` (`cxx:1902-1907`).
    let Some(ofi_face) = ofi.face() else {
        return false;
    };
    let mut fio = Face(ofi_face.0.clone());
    if let Some(m) = mes.get(&shape_map_key(&fio.0)) {
        fio = Face(m.clone());
    }
    // `BRepAdaptor_Surface BAsurf(FIO);` (`cxx:1908`).
    let basurf = SurfaceAdaptor::of_face(&fio);

    // `TopExp_Explorer exp(FI.Oriented(TopAbs_FORWARD), TopAbs_WIRE)`
    // (`cxx:1909`).
    let fi_forward = Face(fi.0.oriented(Orientation::Forward));
    for w in explorer_shapes(&fi_forward.0, ShapeType::Wire) {
        let wire = Wire(w);
        // `wexp.Init(W.Oriented(FORWARD), FI.Oriented(FORWARD))`
        // (`cxx:1921-1925`).
        let mut wexp = WireExplorer::new();
        wexp.init(&wire, Some(&fi_forward));
        // `if (!wexp.More()) continue;` (`cxx:1926-1929`).
        let Some(first_e) = wexp.current_edge() else {
            continue;
        };

        let mut cur_e = first_e.clone();
        let mut end = false;
        while !end {
            // `cxx:1932-1945`.
            let next_e = if {
                wexp.next();
                wexp.more()
            } {
                // `wexp.More()`: `NextE = wexp.Current();`.
                match wexp.current_edge() {
                    Some(e) => e,
                    None => break,
                }
            } else {
                // `NextE = FirstE; end = true;`.
                end = true;
                first_e.clone()
            };

            // `if (CurE.IsSame(NextE)) continue;` (`cxx:1946-1949`).
            if is_same(&cur_e.0, &next_e.0) {
                continue;
            }

            // `TopoDS_Vertex Vref = CommonVertex(CurE, NextE);` (`cxx:1948`).
            let Some(vref) = common_vertex(&cur_e, &next_e) else {
                continue;
            };

            // `CurE = Analyse.EdgeReplacement(FI, CurE);` and the same for
            // `NextE` (`cxx:1950-1951`).
            let cur_rep = analyse.edge_replacement(fi, &cur_e);
            let next_rep = analyse.edge_replacement(fi, &next_e);

            // `OFI.Generated(CurE)` / `OFI.Generated(NextE)` (`cxx:1953-1959`).
            let (Some(ceo_shape), Some(neo_shape)) =
                (ofi.generated(&cur_rep.0), ofi.generated(&next_rep.0))
            else {
                if let Some(c) = wexp.current_edge() {
                    cur_e = c;
                }
                continue;
            };
            let ceo = Edge(ceo_shape);
            let neo = Edge(neo_shape);

            // `cxx:1960-2000`: resolve the pair into two oriented chains.
            let cur_bound = build.contains_key(&shape_map_key(&cur_rep.0));
            let next_bound = build.contains_key(&shape_map_key(&next_rep.0));
            let ceo_in_mes = mes.contains_key(&shape_map_key(&ceo.0));
            let neo_in_mes = mes.contains_key(&shape_map_key(&neo.0));

            let mut do_inter = false;
            let mut or1 = Orientation::External;
            let mut or2 = Orientation::External;
            let mut choice = 0;
            let mut ne1seq: EdgeChain = Vec::new();
            let mut ne2seq: EdgeChain = Vec::new();

            if cur_bound && next_bound {
                // `cxx:1967-1977`.
                do_inter = true;
                choice = 1;
                if let Some(ne1) = build.get(&shape_map_key(&cur_rep.0)) {
                    get_edges_oriented_in_face(ne1, &fio, as_des, &mut ne1seq);
                }
                if let Some(ne2) = build.get(&shape_map_key(&next_rep.0)) {
                    get_edges_oriented_in_face(ne2, &fio, as_des, &mut ne2seq);
                }
                or1 = Orientation::Reversed;
                or2 = Orientation::Forward;
            } else if cur_bound && neo_in_mes {
                // `cxx:1978-1988`.
                do_inter = true;
                choice = 2;
                if let Some(ne1) = build.get(&shape_map_key(&cur_rep.0)) {
                    get_edges_oriented_in_face(ne1, &fio, as_des, &mut ne1seq);
                }
                if let Some(ne2) = mes.get(&shape_map_key(&neo.0)) {
                    ne2seq.push(Edge(ne2.clone().oriented(next_rep.0.orientation())));
                }
                or1 = Orientation::Reversed;
                or2 = Orientation::Forward;
            } else if next_bound && ceo_in_mes {
                // `cxx:1989-1999`.
                do_inter = true;
                choice = 3;
                if let Some(ne1) = build.get(&shape_map_key(&next_rep.0)) {
                    get_edges_oriented_in_face(ne1, &fio, as_des, &mut ne1seq);
                }
                if let Some(ne2) = mes.get(&shape_map_key(&ceo.0)) {
                    ne2seq.push(Edge(ne2.clone().oriented(cur_rep.0.orientation())));
                }
                or1 = Orientation::Forward;
                or2 = Orientation::Reversed;
            }
            // else `cxx:1999-2003`: `DoInter = false;`.

            if do_inter {
                // `cxx:2008-2018`: `NE1` / `NE2` can be compounds.
                let pair = if choice == 1 || choice == 2 {
                    (ne1seq.last().cloned(), ne2seq.first().cloned())
                } else {
                    (ne1seq.first().cloned(), ne2seq.last().cloned())
                };
                // Port guard: `Last()` / `First()` of an empty list raises.
                let (Some(a_e1), Some(a_e2)) = pair else {
                    if let Some(c) = wexp.current_edge() {
                        cur_e = c;
                    }
                    continue;
                };
                // `cxx:2020-2028`.
                if a_e1.0.orientation() == Orientation::Reversed {
                    or1 = or1.reversed();
                }
                if a_e2.0.orientation() == Orientation::Reversed {
                    or2 = or2.reversed();
                }

                let mut b_coincide = false;
                // `RefEdgeInter(FIO, BAsurf, aE1, aE2, anOr1, anOr2, AsDes2d,
                //  Tol, true, Vref, theImageVV, theDMVV, bCoincide)`
                // (`cxx:2031-2042`).
                ref_edge_inter(
                    &fio,
                    &basurf,
                    &a_e1,
                    &a_e2,
                    or1,
                    or2,
                    as_des2d,
                    tol,
                    true,
                    &vref,
                    data.image_vv,
                    data.dmvv,
                    &mut b_coincide,
                );

                // `cxx:2044-2065`: both directions of `theEdgeIntEdges`.
                data.edge_int_edges
                    .entry(shape_map_key(&a_e1.0))
                    .or_default()
                    .push(a_e2.0.clone());
                data.edge_int_edges
                    .entry(shape_map_key(&a_e2.0))
                    .or_default()
                    .push(a_e1.0.clone());

                // `cxx:2067-2072`: the offset edges of the common vertex exist.
                if build.contains_key(&shape_map_key(&vref.0)) {
                    if !data.faces_with_verts.iter().any(|f| is_same(f, &fi.0)) {
                        data.faces_with_verts.push(fi.0.clone());
                    }
                }
            } else {
                // `cxx:2074-2088`.
                if let Some(v) = common_vertex(&ceo, &neo) {
                    if let Some(m) = mes.get(&shape_map_key(&ceo.0)) {
                        // `UpdateVertex(V, CEO, TopoDS::Edge(MES(CEO)), Tol);`
                        // then `AsDes2d->Add(MES(CEO), V);`.
                        let target = Edge(m.clone());
                        update_vertex(&v, &ceo, &target, tol);
                        as_des2d.add(m, &v.0);
                    }
                    if let Some(m) = mes.get(&shape_map_key(&neo.0)) {
                        let target = Edge(m.clone());
                        update_vertex(&v, &neo, &target, tol);
                        as_des2d.add(m, &v.0);
                    }
                }
            }

            // `CurE = wexp.Current();` (`cxx:2090`).
            if let Some(c) = wexp.current_edge() {
                cur_e = c;
            }
        }
    }
    true
}

/// `ConnexIntByIntInVert(FI, OFI, MES, Build, AsDes, AsDes2d, Tol, Analyse,
/// theDMVV, theRange)` (`cxx:2100-2308`).
///
/// `MES` is read only here, hence `&ShapeMap`.
#[allow(clippy::too_many_arguments)]
pub fn connex_int_by_int_in_vert(
    fi: &Face,
    ofi: &BRepOffsetOffset,
    mes: &ShapeMap,
    build: &ShapeMap,
    as_des: &AsDes,
    as_des2d: &mut AsDes,
    tol: f64,
    analyse: &Analyse,
    dmvv: &mut Dmvv,
) {
    // `TopoDS_Face FIO = TopoDS::Face(OFI.Face());
    //  if (MES.IsBound(FIO)) FIO = TopoDS::Face(MES(FIO));` (`cxx:2114-2118`).
    let Some(ofi_face) = ofi.face() else {
        return;
    };
    let mut fio = Face(ofi_face.0.clone());
    if let Some(m) = mes.get(&shape_map_key(&fio.0)) {
        fio = Face(m.clone());
    }

    // `cxx:2119-2127`: `aME`, the edges `AsDes->Descendant(FIO)`.
    let mut ame: HashSet<ShapeMapKey> = HashSet::new();
    for e in as_des.descendant(&fio.0) {
        ame.insert(shape_map_key(e));
    }

    // `BRepAdaptor_Surface BAsurf(FIO);` (`cxx:2129`).
    let basurf = SurfaceAdaptor::of_face(&fio);

    // `cxx:2131`: the wires of `FI.Oriented(TopAbs_FORWARD)`.
    let fi_forward = Face(fi.0.oriented(Orientation::Forward));
    for w in explorer_shapes(&fi_forward.0, ShapeType::Wire) {
        let wire = Wire(w);
        // `cxx:2143-2150`.
        let mut wexp = WireExplorer::new();
        wexp.init(&wire, Some(&fi_forward));
        let Some(first_e) = wexp.current_edge() else {
            continue;
        };

        let mut cur_e = first_e.clone();
        let mut end = false;
        while !end {
            // `cxx:2152-2167`.
            let next_e = if {
                wexp.next();
                wexp.more()
            } {
                match wexp.current_edge() {
                    Some(e) => e,
                    None => break,
                }
            } else {
                end = true;
                first_e.clone()
            };

            // `if (CurE.IsSame(NextE)) continue;` (`cxx:2168-2171`).
            if is_same(&cur_e.0, &next_e.0) {
                continue;
            }

            // `TopoDS_Vertex Vref = CommonVertex(CurE, NextE);
            //  if (!Build.IsBound(Vref)) { CurE = NextE; continue; }`
            // (`cxx:2170-2177`).
            let Some(vref) = common_vertex(&cur_e, &next_e) else {
                cur_e = next_e;
                continue;
            };
            if !build.contains_key(&shape_map_key(&vref.0)) {
                cur_e = next_e;
                continue;
            }

            // `cxx:2179-2185`.
            let cur_rep = analyse.edge_replacement(fi, &cur_e);
            let next_rep = analyse.edge_replacement(fi, &next_e);
            let (Some(ceo_shape), Some(neo_shape)) =
                (ofi.generated(&cur_rep.0), ofi.generated(&next_rep.0))
            else {
                if let Some(c) = wexp.current_edge() {
                    cur_e = c;
                }
                continue;
            };
            let ceo = Edge(ceo_shape);
            let neo = Edge(neo_shape);

            // `cxx:2186-2208`: the two images, no orientation override
            // (`anOr1` / `anOr2` stay `TopAbs_EXTERNAL`).
            let cur_bound = build.contains_key(&shape_map_key(&cur_rep.0));
            let next_bound = build.contains_key(&shape_map_key(&next_rep.0));
            let ne1: TopoShape;
            let ne2: TopoShape;
            if cur_bound && next_bound {
                ne1 = build[&shape_map_key(&cur_rep.0)].clone();
                ne2 = build[&shape_map_key(&next_rep.0)].clone();
            } else if cur_bound && mes.contains_key(&shape_map_key(&neo.0)) {
                ne1 = build[&shape_map_key(&cur_rep.0)].clone();
                ne2 = mes[&shape_map_key(&neo.0)].clone();
            } else if next_bound && mes.contains_key(&shape_map_key(&ceo.0)) {
                ne1 = build[&shape_map_key(&next_rep.0)].clone();
                ne2 = mes[&shape_map_key(&ceo.0)].clone();
            } else {
                // `CurE = wexp.Current(); continue;` (`cxx:2204-2207`).
                if let Some(c) = wexp.current_edge() {
                    cur_e = c;
                }
                continue;
            }

            // `const TopoDS_Shape& NE3 = Build(Vref);` (`cxx:2215`), bound by
            // the guard above.
            let Some(ne3) = build.get(&shape_map_key(&vref.0)).cloned() else {
                if let Some(c) = wexp.current_edge() {
                    cur_e = c;
                }
                continue;
            };

            // `cxx:2216-2303`: every edge of `NE3` that lies on the face.
            for a_e3_shape in explorer_shapes(&ne3, ShapeType::Edge) {
                // `if (!aME.Contains(aE3)) continue;` (`cxx:2219-2222`).
                if !ame.contains(&shape_map_key(&a_e3_shape)) {
                    continue;
                }
                let a_e3 = Edge(a_e3_shape.clone());

                // `cxx:2224-2246`: against `NE1`.
                for a_e1 in explorer_shapes(&ne1, ShapeType::Edge) {
                    let mut empty_image = BRepAlgoImage::new();
                    let mut b_coincide = false;
                    ref_edge_inter(
                        &fio,
                        &basurf,
                        &Edge(a_e1.clone()),
                        &a_e3,
                        Orientation::External,
                        Orientation::External,
                        as_des2d,
                        tol,
                        true,
                        &vref,
                        &mut empty_image,
                        dmvv,
                        &mut b_coincide,
                    );
                    if b_coincide {
                        // `Store(aE3, AsDes2d->Descendant(aE1), Tol, true,
                        //  AsDes2d, theDMVV)` (`cxx:2245`).
                        let lv: Vec<TopoShape> = as_des2d.descendant(&a_e1).to_vec();
                        store_on_edge(&a_e3.0, &lv, tol, true, as_des2d, dmvv);
                    }
                }

                // `cxx:2248-2269`: against `NE2`.
                for a_e2 in explorer_shapes(&ne2, ShapeType::Edge) {
                    let mut empty_image = BRepAlgoImage::new();
                    let mut b_coincide = false;
                    ref_edge_inter(
                        &fio,
                        &basurf,
                        &Edge(a_e2.clone()),
                        &a_e3,
                        Orientation::External,
                        Orientation::External,
                        as_des2d,
                        tol,
                        true,
                        &vref,
                        &mut empty_image,
                        dmvv,
                        &mut b_coincide,
                    );
                    if b_coincide {
                        // `cxx:2268`.
                        let lv: Vec<TopoShape> = as_des2d.descendant(&a_e2).to_vec();
                        store_on_edge(&a_e3.0, &lv, tol, true, as_des2d, dmvv);
                    }
                }

                // `cxx:2271-2302`: among themselves, starting after `aE3`.
                let ne3_edges = explorer_shapes(&ne3, ShapeType::Edge);
                let Some(pos) = ne3_edges.iter().position(|x| is_same(x, &a_e3.0)) else {
                    continue;
                };
                for a_e3_next in ne3_edges.iter().skip(pos + 1) {
                    // `if (aME.Contains(aE3Next))` (`cxx:2284`).
                    if !ame.contains(&shape_map_key(a_e3_next)) {
                        continue;
                    }
                    let mut empty_image = BRepAlgoImage::new();
                    let mut b_coincide = false;
                    ref_edge_inter(
                        &fio,
                        &basurf,
                        &Edge(a_e3_next.clone()),
                        &a_e3,
                        Orientation::External,
                        Orientation::External,
                        as_des2d,
                        tol,
                        true,
                        &vref,
                        &mut empty_image,
                        dmvv,
                        &mut b_coincide,
                    );
                }
            }

            // `CurE = wexp.Current();` (`cxx:2304`).
            if let Some(c) = wexp.current_edge() {
                cur_e = c;
            }
        }
    }
}
